-- Generated by scripts/build_compiled.py from src/fraudrules/rules/money-mule/mu-001-rapid-pass-through.yaml. Do not edit.
-- MU-001 New account sends out most of what it received in the last three days
SELECT 'MU-001' AS rule_id, 'transactions' AS anchor_table, a.id AS anchor_id
FROM transactions AS a
JOIN transactions AS b ON b.account_id = a.account_id AND b.ts <= a.ts AND b.ts > a.ts - 259200
WHERE (a.direction = 'out' AND a.channel IN ('wire', 'ach', 'rtp', 'p2p') AND a.ts < (a.account_opened_ts + 7776000)) AND (b.direction = 'in' AND b.txn_type <> 'return')
GROUP BY a.id
HAVING (SUM(b.amount_cents) >= 200000 AND MAX(a.amount_cents) * 100 >= SUM(b.amount_cents) * 80);
